params.query:
SELECT DISTINCT ?player ?playerLabel ?birthdate ?wnbaId ?brefId WHERE {
  ?team wdt:P118 wd:Q2593221 ; wdt:P31 ?teamType . ?teamType rdfs:label "basketball team"@en .
  ?player wdt:P54 ?team .
  OPTIONAL { ?player wdt:P569 ?birthdate }
  OPTIONAL { ?player wdt:P3588 ?wnbaId }
  OPTIONAL { ?player wdt:P4561 ?brefId }
  SERVICE wikibase:label { bd:serviceParam wikibase:language "en". }
}
